<body>
<div id="app">
  <header>
    <h1>🚢 ТИТАНИК — Симулятор крушения</h1>
    <div id="clock">15.04.1912, 23:40</div>
  </header>

  <div id="main">
    <div class="panel" id="vizWrap">
      <div class="panel-title">Погружение корабля (профиль)</div>
      <canvas id="viz"></canvas>
    </div>

    <div id="side">
      <div class="panel" id="graphWrap">
        <div class="panel-title">Затопление отсеков (доля воды)</div>
        <canvas id="graph"></canvas>
      </div>
