      </div>
      <small id="speedInfo">Симуляция в реальном времени</small>
    </div>
  </div>
</div>

<script>
(function() {
  "use strict";

  // ================= МОДЕЛЬ ТИТАНИКА =================
  // Реальный хронологический интервал: крушение в 23:40, посадка на дно ~02:20.
  // Общее время с момента столкновения: ~155 минут.
  const TOTAL_MIN = 155;          // полные минуты симуляции
  const DEPTH_M = 10;             // начальная осадка (м)
  const SHIP_LEN_M = 269;         // длина (м)

  // Отсеки: 0 — нос (вперед), N-1 — корма.
  const N = 14;                   // число водонепроницаемых отсеков
  const BREACH_START = 0;         // breached отсеки (профиль пробоины)
  const BREACH_END = 4;           // первые 5 отсеков затоплены пробиной от айсберга

  // ================= ПАРАМЕТРЫ ФИЗИКИ =================
  const G = 9.81;
  const RHO = 1025;               // плотность морской воды (кг/м3)
  const CD = 0.62;                // коэффициент расхода для пробоины
  const CWH = 0.55;               // коэффициент расхода для переливания через переборку
  const DECK_H = 12;              // высота откиель/палуба (м, относительно ватершипа)

  // ================= СОСТОЯНИЕ =================
  let state;
  let lastTime = 0;

  function newState() {
    const compartments = [];
    for (let i = 0; i < N; i++) {
      compartments.push({
        i: i,
        flood: 0,        // доля заполнения водой 0..1 (уровень относительно палубы)
        overflow: 0,     // доля переливания через переборку (для графики)
        filledFromPrev: false
      });
    }
    return {
      timeMin: 0,        // время в симуляции (мин)
      speed: 1,
      playing: false,
      breakProgress: 0,  // 0 — цела, 1 — разлом
      sternPhase: 0,     // 0 — в воде, 1 — отрыв кормы, 2 — на дне
      compartments: compartments,
      // Для графики затопления (история)
      history: [],
      events: [],
      eventIdx: 0
    };
  }

  // Физический шаг интеграции (модель торричелли + переливание)
  function stepPhysics(dt) {
    const S = state;
    const compartments = S.compartments;

    // 1) приток из моря в проинированные отсеки
    for (let i = 0; i < N; i++) {
      const c = compartments[i];
      c.seaInflow = 0;
      if (i >= BREACH_START && i <= BREACH_END) {
        // головной напор = уровень моря (0) минус уровень воды в отсеке
        // flood измеряется относительно палубы: уровень воды = flood*DECK_H (вниз)
        // напор (м) = DECK_H*(1-flood)  (чем больше пустой отсек — тем больше напор)
        const head = DECK_H * (1 - Math.min(c.flood, 1));
        if (head > 0) {
          const A_open = 2.2 + 0.6 * i; // площадь пробоины растёт к носу
          const q = CD * A_open * Math.sqrt(2 * G * head); // м3/с
          c.seaInflow = q;
        }
      }
    }

    // 2) переливание через переборки (от нос к корме)
    for (let i = 0; i < N; i++) {
      c = compartments[i];
      c.overflow = 0;
      if (i < N - 1) {
        const head_over = c.flood - 0.92; // переливание при заполнении >92%
        if (head_over > 0) {
          const L_bf = SHIP_LEN_M / N;
          const q = CWH * L_bf * Math.pow(head_over, 1.5) * Math.sqrt(2 * G);
          c.overflow = Math.min(q, c.seaInflow + (i > 0 ? compartments[i-1].overflow : 0) + 5);
        }
      }
    }

    // 3) интегрирование заполнения
    const dt_s = dt * S.speed; // секунды (с учётом скорости) — но dt в мин, конвертируем
    const dtSec = dt * 60 * S.speed;
    for (let i = 0; i < N; i++) {
      const c = compartments[i];
      // Объём отсе Approx (м3): длина * ширина * высота
      const V = (SHIP_LEN_M / N) * 28 * DECK_H; // м3
      // приток: из моря + из переднего отсека (перелив) минус перелив в задний
      let netInflow = c.seaInflow + (i > 0 ? compartments[i-1].overflow : 0) - c.overflow;
      // изменение доли заполнения
      let dFlood = (netInflow * dtSec) / V;
      // нелинейность: при большом притоке быстрее
      c.flood = Math.min(1.05, c.flood + dFlood);
      if (c.flood < 0) c.flood = 0;
    }

    // Собираем историю (каждые ~0.25 мин)
    S.history.push({
      t: S.timeMin,
      floods: compartments.map(c => c.flood)
    });
    if (S.history.length > 2000) S.history.shift();
  }

  // ================= ВЫЧИСЛЕНИЕ ПОГРУЖЕНИЯ =================
  function computeSinking() {
    const S = state;
    const c = S.compartments;

    // Вес/плавучесть: общий затоплённый объём
    let totalFloodVol = 0;
    for (let i = 0; i < N; i++) totalFloodVol += c[i].flood;
    // Плавучесть обратно к оставшемуся объёму
    const buoyancy = Math.max(0, 1 - totalFloodVol / (N * 1.15));

    // Дифферент: взвешенный центр затопления vs центр плавучести (геом. центр = 0.5)
    let foreMoment = 0;
    for (let i = 0; i < N; i++) {
      const x = (i + 0.5) / N; // 0..1 по длине (0 — нос)
      foreMoment += x * c[i].flood;
    }
    const centerFlood = foreMoment / (totalFloodVol + 1e-6);
    // Разница центра затопления (вперёд от центра) → дифферент на нос
    const trimDiff = centerFlood - 0.5; // положит → нос глубже
    const trimAngle = Math.min(0.75, Math.max(-0.05, trimDiff * 2.4)); // рад

    // Разлом: начинается при большом дифферете и заполнении носовой части
    // По истории: ~2:05–2:10, т.е. ~95–105 мин
    const breakTrigger = Math.min(1, Math.max(0,
      (S.timeMin - 95) / 20));
    // Усиливается дифферетом
    S.breakProgress = Math.min(1, breakTrigger * (0.4 + Math.max(0, trimAngle) * 2));

    // Фаза кормы: после разлома корма поднимается и отрывается
    S.sternPhase = S.breakProgress > 0.5 ? Math.min(1, (S.breakProgress - 0.5) * 2) : 0;

    // Осадка (посадка на дно): увеличивается с затоплением
    const draft = DEPTH_M + 35 * Math.min(1, totalFloodVol / N);

    return {
      buoyancy,
      trimAngle,
      totalFloodVol,
      draft,
      breakProgress: S.breakProgress,
      sternPhase: S.sternPhase
    };
  }

  // ================= СОБЫТИЯ / СТАТУС =================
  const EVENTS = [
    { t: 0,    text: "Столкновение с айсбергом. Пробины в первых 5 отсеках." },
    { t: 10,   text: "Отсеки затоплены. Корабль начинает дифферент на нос." },
    { t: 30,   text: "Начало спуска спасательных boat." },
    { t: 45,   text: "Дифферент усиливается. Палубы носовой надстройки погружаются." },
    { t: 70,   text: "Огни на палубе погашены (отключение электропитания)." },
    { t: 95,   text: "Носовая часть погружается почти вертикально." },
    { t: 105,  text: "Разлом корпуса на составные части (мидель)." },
    { t: 115,  text: "Корма поднимается вверх." },
    { t: 125,  text: "Корма отрывается от поверхности." },
    { t: 135,  text: "Корма погружается." },
    { t: 150,  text: "Корабль лёг на дно. Погружение завершено." }
  ];

  function updateStatus() {
    const S = state;
    const info = computeSinking();
    // Время
    const totalSec = 23*3600 + 40*60 + S.timeMin*60; // секунды от суток
    const hh = Math.floor(totalSec/3600) % 24;
    const mm = Math.floor(totalSec/60) % 60;
    document.getElementById('clock').textContent =
      "15.04.1912, " + String(hh).padStart(2,'0') + ":" + String(mm).padStart(2,'0');

    // Статус-текст
    let status = "Дрейф";
    for (let k = EVENTS.length - 1; k >= 0; k--) {
      if (S.timeMin >= EVENTS[k].t) { status = EVENTS[k].text; break; }
    }
    if (S.timeMin >= 152) status = "Корабль на дне. Погружение завершено.";
    document.getElementById('statusText').textContent = status;

    // Статистика
    const trimDeg = info.trimAngle * 180 / Math.PI;
    document.getElementById('stats').innerHTML =
      "Состояние: <b>" + (S.breakProgress >= 1 ? "Разлом завершён" :
        S.sternPhase >= 1 ? "Корма оторвана" :
        info.buoyancy > 0.5 ? "Водонепроницаемый" : "Посадка на дно") + "</b><br>" +
      "Осадка носа: <b>" + info.draft.toFixed(1) + " м</b><br>" +
      "Дифферент: <b>" + trimDeg.toFixed(1) + "°</b> (на нос)<br>" +
      "Плавучесть: <b>" + (info.buoyancy*100).toFixed(0) + "%</b><br>" +
      "Водоизмерение затопления: <b>" + info.totalFloodVol.toFixed(1) + "</b><br>" +
      "Перелом: <b>" + (S.breakProgress*100).toFixed(0) + "%</b>";
  }

  // ================= РЕНДЕРИНГ ВИЗУАЛЯ =================
  const viz = document.getElementById('viz');
  const vctx = viz.getContext('2d');
  let vw, vh;

  function resizeViz() {
    const rect = viz.parentElement.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    viz.width = rect.width * dpr;
    viz.height = rect.height * dpr;
    vctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    vw = rect.width; vh = rect.height;
  }

  function drawViz() {
    vctx.clearRect(0, 0, vw, vh);
    const info = computeSinking();
    const S = state;

    // морская поверхность (уровень)
    const seaY = vh * 0.32;
    // вода за пределами корабля
    const grd = vctx.createLinearGradient(0, seaY, 0, vh);
    grd.addColorStop(0, "#0e3a5e");
    grd.addColorStop(1, "#061826");
    vctx.fillStyle = grd;
    vctx.fillRect(0, seaY, vw, vh - seaY);

    // волны на поверхности
    vctx.strokeStyle = "rgba(150,200,240,0.25)";
    vctx.lineWidth = 1;
    const t = performance.now() * 0.001;
    vctx.beginPath();
    for (let x = 0; x <= vw; x += 12) {
      const y = seaY + Math.sin(x*0.03 + t*1.5) * 2 + Math.sin(x*0.01 + t*0.7)*3;
      if (x === 0) vctx.moveTo(x, y); else vctx.lineTo(x, y);
    }
    vctx.stroke();

    // Координаты корабля: x в пикселях от 0 (корма) до vw (нос)
    const shipScale = vw * 0.78;
    const cx = vw * 0.5; // центр корабля в пикселях
    const halfLen = shipScale / 2;

    // Дифферент (положитетельный → нос вниз) и фаза кормы
    const trim = info.trimAngle;
    const breakP = info.breakProgress;
    const sternP = info.sternPhase;

    // Рисуем корпус: две половины (передняя/носовая и кормовая) при разломе
    // Носовая часть (0..0.5 длины) и кормовая (0.5..1)
    // Определим углы и позиции каждой половины
    // Нос: угол = trim (вниз), вокруг точки разлома (мидель)
    // Корма: угол зависит от sternPhase (поднимается)

    const hullH = Math.min(70, vh * 0.16); // высота корпуса
    const freeboard = hullH * 0.35;       // надводная часть
    const deckY = -freeboard;             // палуба (относительно ватершипа)
    const keelY = hullH - freeboard;      // киель

    // функция для точки на корпусе (в мировых координатах корабля)
    // u: 0 корма .. 1 нос; v: -1 палуба .. 1 киель
    // возвращает {x,y} уже с учётом трансформации
    function worldToScreen(u, v, extraAngle, pivotU) {
      // базовые координаты
      let lx = cx + (u - 0.5) * shipScale;
      let ly = seaY + v * hullH;
      // поворот вокруг pivotU (мидель)
      const ang = extraAngle;
      if (ang !== 0) {
        const pu = cx + (pivotU - 0.5) * shipScale;
        const pv = seaY;
        const dx = lx - pu, dy = ly - pv;
        lx = pu + dx * Math.cos(ang) - dy * Math.sin(ang);
        ly = pv + dx * Math.sin(ang) + dy * Math.cos(ang);
      }
      return { x: lx, y: ly };
    }

    // 1) КОРМОВАЯ ПОЛОВИНА (0 .. 0.5)
    // при sternPhase>0 корма поднимается (отрицательный угол → корма вверх)
    const sternAngle = -sternP * 0.6; // корма поднимается
    // очертания кормовой половины
    function hullPoint(u, v) {
      // форма корпуса: сужение к носу и корме
      let w = 1;
      if (u > 0.5) w = 1 - (u - 0.5) * 1.2;      // нос сужается
      else w = 1 - (0.5 - u) * 0.7;              // корма чуть шире
      if (w < 0.15) w = 0.15;
      return [u, v * w];
    }
    // рисуем кормовую полосу
    vctx.save();
    const sternPts = [];
    const Nsamples = 30;
    // Верх (палуба) кормы
    for (let s = 0; s <= Nsamples; s++) {
      const u = 0.5 - (s / Nsamples) * 0.5; // 0.5 → 0
      const [uu, ww] = hullPoint(u, -1); // палуба v=-1
      sternPts.push(worldToScreen(uu, ww, sternAngle, 0.5));
    }
    // Низ (киель) кормы
    for (let s = 0; s <= Nsamples; s++) {
      const u = 0.5 - (s / Nsamples) * 0.5;
      const [uu, ww] = hullPoint(u, 1); // киель
      sternPts.push(worldToScreen(uu, ww, sternAngle, 0.5));
    }
    vctx.beginPath();
    vctx.moveTo(sternPts[0].x, sternPts[0].y);
    for (let i = 1; i < sternPts.length; i++) vctx.lineTo(sternPts[i].x, sternPts[i].y);
    vctx.closePath();
    vctx.fillStyle = "#3a4152";
    vctx.fill();
    vctx.lineWidth = 2;
    vctx.strokeStyle = "#8892a5";
    vctx.stroke();
    // надостройки на корме
    vctx.fillStyle = "#d9d9d9";
    // найдём палубу кормы (среднее)
    const sternDeck = worldToScreen(0.25, -1, sternAngle, 0.5);
    vctx.fillRect(sternDeck.x - 8, sternDeck.y - 24, 16, 24);
    // дымовые трубы на корме
    vctx.fillStyle = "#2a2a2a";
    for (let k = 0; k < 3; k++) {
      const tx = sternDeck.x - 6 + k * 6;
      vctx.fillStyle = k < 2 ? "#e8e8e8" : "#c94f4f";
      vctx.fillRect(tx, sternDeck.y - 40 - k*0, 4, 16);
    }
    vctx.restore();

    // 2) НОСКАЯ ПОЛОВИНА (0.5 .. 1)
    const bowAngle = trim; // нос погружается
    const bowPts = [];
    for (let s = 0; s <= Nsamples; s++) {
      const u = 0.5 + (s / Nsamples) * 0.5; // 0.5 → 1
      const [uu, ww] = hullPoint(u, -1);
      bowPts.push(worldToScreen(uu, ww, bowAngle, 0.5));
    }
    for (let s = 0; s <= Nsamples; s++) {
      const u = 0.5 + (s / Nsamples) * 0.5;
      const [uu, ww] = hullPoint(u, 1);
      bowPts.push(worldToScreen(uu, ww, bowAngle, 0.5));
    }
    vctx.beginPath();
    vctx.moveTo(bowPts[0].x, bowPts[0].y);
    for (let i = 1; i < bowPts.length; i++) vctx.lineTo(bowPts[i].x, bowPts[i].y);
    vctx.closePath();
    // градиент корпуса (затоплённая часть темнее)
    const bg = vctx.createLinearGradient(0, seaY - hullH, 0, seaY + hullH);
    bg.addColorStop(0, "#5a6377");
    bg.addColorStop(1, "#2b3240");
    vctx.fillStyle = bg;
    vctx.fill();
    vctx.lineWidth = 2;
    vctx.strokeStyle = "#a0abd8";
    vctx.stroke();

    // 3) Внутренняя заливка в отсеках носовой части (показ через корпус)
    // Оси отсеков: i в мировых координатах u = (i+0.5)/N
    vctx.save();
    // создаём маску-обрезку по носовой части
    vctx.beginPath();
    vctx.moveTo(bowPts[0].x, bowPts[0].y);
    for (let i = 1; i < bowPts.length; i++) vctx.lineTo(bowPts[i].x, bowPts[i].y);
    vctx.closePath();
    vctx.clip();
    for (let i = 0; i <= 5 && i < N; i++) {
      const c = state.compartments[i];
      const uF = (i+0.5)/N;
      const waterLevelV = -1 + c.flood; // v=-1 пустой, v=1 палуба (на самом деле flood от 0..1 => от киеля к палубе)
      // На самом деле: при flood=0 — киель (вниз), при flood=1 — палуба
      // v: -1 палуба, 1 киель. уровень воды = палуба + (1-flood)*(киель-палуба)
      const wl = worldToScreen(uF, -1 + (1 - c.flood) * 2, bowAngle, 0.5);
      // рисуем воду как вертикальную полосу от уровня воды до киеля
      const bottom = worldToScreen(uF, 1, bowAngle, 0.5);
      const x = wl.x;
      const grad = vctx.createLinearGradient(0, wl.y, 0, bottom.y);
      grad.addColorStop(0, "rgba(60,120,180,0.55)");
      grad.addColorStop(1, "rgba(30,70,120,0.75)");
      vctx.fillStyle = grad;
      // ширина отсека
      const uNext = (i+1.5)/N;
      const wNext = worldToScreen(uNext, -1 + (1 - state.compartments[i+1 < N ? i+1 : i].flood)*2, bowAngle, 0.5);
      vctx.beginPath();
      vctx.moveTo(x, wl.y);
      vctx.lineTo(wNext.x, wNext.y);
      vctx.lineTo(bottom.x, bottom.y);
      vctx.closePath();
      vctx.fill();
    }
    vctx.restore();

    // 4) Ватершип / вмерзший уровень на поверхности
    // мачты / флаг
    const bowDeck = worldToScreen(0.92, -1, bowAngle, 0.5);
    vctx.fillStyle = "#333";
    vctx.fillRect(bowDeck.x, bowDeck.y - 30, 2, 30);
    // пар из отсеков (визуальный эффект затопления)
    if (info.totalFloodVol > 2) {
      vctx.fillStyle = "rgba(200,220,240,0.15)";
      for (let k = 0; k < 6; k++) {
        const px = bowDeck.x - 40 + k * 16 + Math.sin(performance.now()*0.002+k)*4;
        const py = bowDeck.y - 40 - k*10 - performance.now()*0.02 % 40;
        vctx.fillRect(px, py, 3, 8);
      }
    }

    // 5) Индикатор линии воды (базовый ватершип)
    vctx.strokeStyle = "rgba(120,180,220,0.4)";
    vctx.setLineDash([6, 6]);
    vctx.beginPath();
    vctx.moveTo(0, seaY); vctx.lineTo(vw, seaY);
    vctx.stroke();
    vctx.setLineDash([]);

    // подписи
    vctx.fillStyle = "rgba(180,200,220,0.7)";
    vctx.font = "11px sans-serif";
    vctx.fillText("НОС ▸", vw - 60, seaY - 8);
    vctx.fillText("▸ КОРМА", 8, seaY - 8);
  }

  // ================= РЕНДЕРИНГ ГРАФИКА =================
  const graph = document.getElementById('graph');
  const gctx = graph.getContext('2d');
  let gw, gh;
  const GRAPH_COLORS = [
    "#ff5a5a", "#ff9f43", "#ffd23f", "#a8e063", "#56ab2f",
    "#4ec9c0", "#45b7d1", "#6a8feb", "#845ef7", "#d980ff",
    "#ff6b6b", "#c96fc5", "#f77fb2", "#f093fb"
  ];

  function resizeGraph() {
    const rect = graph.parentElement.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    graph.width = rect.width * dpr;
    graph.height = rect.height * dpr;
    gctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    gw = rect.width; gh = rect.height;
  }

  function drawGraph() {
    gctx.clearRect(0, 0, gw, gh);
    const S = state;
    const pad = { l: 36, r: 8, t: 8, b: 22 };
    const w = gw - pad.l - pad.r;
    const h = gh - pad.t - pad.b;

    // Оси
    gctx.strokeStyle = "#2a3548";
    gctx.lineWidth = 1;
    gctx.beginPath();
    gctx.moveTo(pad.l, pad.t);
    gctx.lineTo(pad.l, pad.t + h);
    gctx.lineTo(pad.l + w, pad.t + h);
    gctx.stroke();

    // Сетка и подписи по Y (0..1)
    gctx.fillStyle = "#6b7a8c";
    gctx.font = "10px sans-serif";
    gctx.textAlign = "right";
    for (let v = 0; v <= 1; v += 0.25) {
      const y = pad.t + h - v * h;
      gctx.beginPath();
      gctx.moveTo(pad.l, y);
      gctx.lineTo(pad.l + w, y);
      gctx.strokeStyle = v === 0 ? "#2a3548" : "#1a2333";
      gctx.stroke();
      gctx.fillText((v*100).toFixed(0) + "%", pad.l - 5, y + 3);
    }
    // Подпись оси Y
    gctx.save();
    gctx.translate(12, pad.t + h/2);
    gctx.rotate(-Math.PI/2);
    gctx.textAlign = "center";
    gctx.fillText("Затопление, %", 0, 0);
    gctx.restore();

    // Ось X: по времени (0..TOTAL_MIN)
    gctx.textAlign = "center";
    const t0 = Math.max(0, S.timeMin - TOTAL_MIN * 0.0); // показываем последние? — пока 0..TOTAL_MIN
    for (let tmin = 0; tmin <= TOTAL_MIN; tmin += 30) {
      const x = pad.l + (tmin / TOTAL_MIN) * w;
      gctx.fillText(String(tmin), x, pad.t + h + 14);
      gctx.beginPath();
      gctx.moveTo(x, pad.t); gctx.lineTo(x, pad.t + h);
      gctx.strokeStyle = "#1a2333"; gctx.stroke();
    }
    gctx.fillText("Минут с столкновения", pad.l + w/2, gh - 3);

    // Кривые по отсекам (берём из истории — последние точки)
    const hist = S.history;
    if (hist.length < 2) return;
    // Масштабируем по времени: показываем весь диапазон 0..TOTAL_MIN
    const xOf = (tt) => pad.l + (tt / TOTAL_MIN) * w;

    for (let i = 0; i < N; i++) {
      gctx.beginPath();
      let started = false;
      for (let j = 0; j < hist.length; j++) {
        const tt = hist[j].t;
        if (tt > S.timeMin) break;
        const v = hist[j].floods[i];
        const x = xOf(tt);
        const y = pad.t + h - Math.min(1, v) * h;
        if (!started) { gctx.moveTo(x, y); started = true; }
        else gctx.lineTo(x, y);
      }
      gctx.strokeStyle = GRAPH_COLORS[i % GRAPH_COLORS.length];
      gctx.lineWidth = 1.5;
      gctx.stroke();
    }

    // Текущее положение (вертикальная маркер-линия по текущему времени)
    const xCur = xOf(S.timeMin);
    gctx.strokeStyle = "#ffd27f";
    gctx.lineWidth = 2;
    gctx.beginPath();
    gctx.moveTo(xCur, pad.t); gctx.lineTo(xCur, pad.t + h);
    gctx.stroke();

    // Легенда отсеков (внизу/в панели stats)
    const legend = document.querySelector('.legend');
    if (legend) {
      legend.innerHTML = '';
      for (let i = 0; i < N; i++) {
        const c = document.createElement('div');
        const breached = (i >= BREACH_START && i <= BREACH_END);
        c.innerHTML = "<span class='bar' style='background:" + GRAPH_COLORS[i % GRAPH_COLORS.length] + "'></span>" +
          (breached ? "◀ пробина " : "") + "отсек " + (i+1);
        legend.appendChild(c);
      }
    }
  }

  // ================= УПРАВЛЕНИЕ =================
  const playBtn = document.getElementById('playBtn');
  const restartBtn = document.getElementById('restartBtn');
  const timeline = document.getElementById('timeline');
  const timelineVal = document.getElementById('timelineVal');
  const speedInfo = document.getElementById('speedInfo');

  function setPlaying(p) {
    state.playing = p;
    playBtn.textContent = p ? "⏸ Пауза" : "▶ Играть";
    playBtn.classList.toggle('primary', !p);
  }

  playBtn.addEventListener('click', () => {
    if (state.timeMin >= TOTAL_MIN - 0.5 && !state.playing) {
      restart();
      return;
    }
    setPlaying(!state.playing);
  });

  function restart() {
    state = newState();
    setPlaying(false);
    updateTimelineUI();
  }
  restartBtn.addEventListener('click', restart);

  function updateTimelineUI() {
    const pct = (state.timeMin / TOTAL_MIN) * 100;
    timeline.value = pct;
    timelineVal.textContent = pct.toFixed(0) + "%";
  }

  timeline.addEventListener('input', () => {
    // Перемотка: при паузе меняем время прямо
    const wasPlaying = state.playing;
    if (wasPlaying) setPlaying(false);
    state.timeMin = (parseFloat(timeline.value) / 100) * TOTAL_MIN;
    // переполнить историю для корректного отображения
    state.history = [];
    for (let k = 0; k < 50; k++) {
      state.history.push({ t: state.timeMin, floods: state.compartments.map(c => c.flood) });
    }
    updateTimelineUI();
  });

  document.querySelectorAll('.speed-group button').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.speed-group button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.speed = parseFloat(btn.dataset.speed);
      speedInfo.textContent = "Симуляция: " + state.speed + "× от реального времени";
    });
  });

  // ================= ГЛАВНЫЙ ЦИКЛ =================
  function loop(now) {
    if (!lastTime) lastTime = now;
    let dt = (now - lastTime) / 1000; // секунды реального времени
    lastTime = now;
    if (dt > 0.1) dt = 0.1; // clamp

    if (state.playing) {
      // Минуты симуляции в секунду: за TOTAL_MIN минут — 155 реальных мин при 1x?
      // Упростим: 1x = 1 симуляционная минута в 1 реальную секунду? 
      // Тогда TOTAL_MIN минут = 155 сек = ~2.6 мин реального времени (компрессия для удобного обзора).
      const simMinutesPerRealSec = 1; // 1x: 1 мин симуляции = 1 сек
      state.timeMin += dt * simMinutesPerRealSec * state.speed;
      if (state.timeMin > TOTAL_MIN) {
        state.timeMin = TOTAL_MIN;
        setPlaying(false);
      }
      stepPhysics(dt * simMinutesPerRealSec); // dt в минутах
      updateTimelineUI();
    }

    updateStatus();
    drawViz();
    drawGraph();
    requestAnimationFrame(loop);
  }

  // Инициализация
  function init() {
    state = newState();
    resizeViz();
    resizeGraph();
    updateStatus();
    updateTimelineUI();
    requestAnimationFrame(loop);
  }
  window.addEventListener('resize', () => { resizeViz(); resizeGraph(); });
  init();

})();
</script>
</body>
</html>
```

Этот файл полностью автономный (без CDN). Симулятор включает:

- **Физика погружения**: модель торричелли для притока воды в проинированные отсеки (первые 5) с переливанием через переборки — рекурсивное затопление, как в историческом сценарии. Дифферент на нос вычисляется взвешенным центром затопления, разлом корпуса (мидель) запускается по времени (~95 мин) и усилению дифферета, корма отрывается в фазе после разлома.
- **Визуализация**: профиль корабля на Canvas с поворотом носовой части (дифферент), отдельной кормой (подъём/отрыв), внутренним затоплением отсеков через полупрозрачный корпус, волной и надстройкой.
- **Управление**: Play/Pause, Restart, ползунок хронологии (перемотка), переключатели скорости 1×/2×/5×.
- **График в реальном времени**: 14 кривых затопления отсеков с легендой, осями и маркером текущего времени.

Замечание: симуляция сжата во времени (1 минута события = 1 сек при 1×) для комфортного обзора全过程, а не воспроизводит точный 155-минутный интервал в реальном времени.
